args.arg:


function cpus_map( input )
{
    let map = {};

    input.split( "\n" )
    .filter( ( s ) => s.trim() != "" )
    .forEach(
        ( s ) => {
            let res = key_numbers( s );

            map[ res.key ] = res;
        }
    );

    return map;
}

function key_numbers( input )
{
    let cols = input.split( " " ).filter( ( s ) => s.trim() != "" ).map( ( s ) => s.trim() );

    return {
        key : cols[ 0 ],
        numbers : numbers_from_cols( cols )
    }
}

function numbers_from_cols( cols )
{
    let idle = Number( cols[ 4 ] ) + Number( cols[ 5 ] );
    let non_idle = Number( cols[ 1 ] ) + Number( cols[ 2 ] ) + Number( cols[ 3 ] ) +
                   Number( cols[ 6 ] ) + Number( cols[ 7 ] ) + Number( cols[ 8 ] );
    let total = idle + non_idle;

    return {
        idle,
        non_idle,
        total
    }
}

function calcula_uso_cpu( antes, despues )
{
    let total = despues.numbers.total - antes.numbers.total;
    let idle = despues.numbers.idle - antes.numbers.idle;

    let uso = ( ( total - idle ) / total ) * 100;

    return {
        cpu : despues.key,
        uso
    }
}

function calcula_uso( cpus_antes, cpus_despues )
{
    let ret = [];

    for( const cpu of Object.keys( cpus_despues ) )
    {
        if( ! cpus_antes[ cpu ] ) { continue; }

        let uso = calcula_uso_cpu( cpus_antes[ cpu ], cpus_despues[ cpu ] );

        if( ! uso ) { continue; } 

        ret.push( uso );
    }

    return ret;
}

let stdin_str = "";

for await ( const chunk of process.stdin )
{
    stdin_str += chunk.toString();
}

let parts = stdin_str.toString().split( "---" );

let info_cpus_antes = cpus_map( parts[ 0 ] );
let info_cpus_despues = cpus_map( parts[ 1 ] );

let uso = calcula_uso( info_cpus_antes, info_cpus_despues ); 

console.log( JSON.stringify( uso ) );

layout.border:
{% for uso in ctx %}


        {% if uso.cpu == "cpu" %}
            all:
        {% else %}
            {{ uso.cpu | replace( "cpu", "" ) }}:
        {% endif %}


    {% set porcentaje = ( uso.uso | round ) | int %}
    {% set porcentaje_str = ( porcentaje | string ) + "%" %}
    {% set porcentaje_str_len = porcentaje_str | length %}
    {% for i in range( porcentaje ) %}
        {% if porcentaje_str_len > i %}{{ porcentaje_str[ i ] }}{% else %} {% endif %}
    {% endfor %}
    {{ porcentaje_str[porcentaje:] }}

{% endfor %}
